import { useEffect, useRef, useState } from "react";

const LOGO = "/assets/tactivo-logo-transparent.png";
const STORAGE_KEY = "tactivo-fieldops-production-v2";
const ROLES = ["admin", "supervisor", "technician", "requestor", "viewer"];
const ROLE_LABELS = { admin: "Admin", supervisor: "Supervisor", technician: "Field Technician", requestor: "Requestor", viewer: "Viewer" };
const id = (prefix) => `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}`;
const now = () => new Date().toISOString();
const shortDate = (date) => date ? new Intl.DateTimeFormat("en-ZM", { day: "2-digit", month: "short", year: "numeric" }).format(new Date(date)) : "Not scheduled";
const initials = (name = "") => name.split(" ").filter(Boolean).slice(0, 2).map((part) => part[0]).join("").toUpperCase() || "TU";
const nextReference = (prefix, records) => `${prefix}-${String(records.length + 1).padStart(4, "0")}`;

function createWorkspace() {
  const users = [];
  const sites = [
    ["Refuel — Maintenance Portfolio", "Refuel", "Zambia"], ["Surya Roma", "Surya", "Roma, Lusaka"], ["Surya Mumbwa", "Surya", "Mumbwa"], ["Surya Kapiri Mposhi", "Surya", "Kapiri Mposhi"], ["Shaann Carriers", "Shaann Carriers", "Zambia"], ["Vivo — Zambia Outlets", "Vivo", "All outlets, Zambia"], ["Sapphire — Zambia Outlets", "Sapphire", "All outlets, Zambia"], ["Toyota Zambia — All Outlets", "Toyota Zambia", "All outlets, Zambia"], ["Surya Filling Station — All Outlets", "Surya Filling Station", "All outlets, Zambia"],
  ].map(([name, customer, location]) => ({ id: id("site"), name, customer, location, contact: "Portfolio service desk", status: "Active" }));
  const checklists = [
    { id: "forecourt", name: "Forecourt & fuel automation visit", discipline: "Forecourt", points: ["Verify controller connectivity and alarm status", "Compare tank-gauge reading with daily reconciliation", "Inspect dispenser hose, nozzle, and emergency-stop function", "Confirm POS / payment terminal connectivity"] },
    { id: "storage", name: "UST / AST integrity inspection", discipline: "Fuel storage", points: ["Inspect tank exterior, bund, vents, and visible joints", "Check leak-detection and overfill alerts", "Verify fill-point and earthing connection condition", "Record corrective action for any integrity finding"] },
    { id: "it", name: "IT, network & security health check", discipline: "IT & security", points: ["Test router, switch, and UPS status", "Confirm NVR recording and camera live view", "Verify LAN/WAN resilience", "Confirm critical updates and backup status"] },
    { id: "solar", name: "Solar & power continuity visit", discipline: "Solar & power", points: ["Inspect panel condition and shading", "Check inverter alarms and output stability", "Review battery charge and terminal condition", "Inspect breakers and earthing"] },
  ];
  const technicianProfiles = users.filter((user) => user.role === "technician").map((user) => ({ id: id("profile"), userId: user.id, phone: "", region: "Zambia", skills: ["Forecourt automation", "Fuel dispensing", "IT & security"], certifications: [], availability: "Available" }));
  return { users, sites, assets: [], requests: [], workOrders: [], checklists, technicianProfiles, activities: [{ id: id("activity"), message: "Tactivo customer portfolio is ready for service planning.", actorId: "admin-001", createdAt: now() }] };
}

function defaultProfiles(users = []) { return users.filter((user) => user.role === "technician").map((user) => ({ id: id("profile"), userId: user.id, phone: "", region: "Zambia", skills: [], certifications: [], availability: "Available" })); }
function readWorkspace() { try { const parsed = JSON.parse(window.localStorage.getItem(STORAGE_KEY)); return parsed?.users && parsed?.sites ? { ...parsed, technicianProfiles: parsed.technicianProfiles || defaultProfiles(parsed.users) } : createWorkspace(); } catch { return createWorkspace(); } }
function canManage(role) { return role === "admin" || role === "supervisor"; }
function canCreateRequest(role) { return canManage(role) || role === "requestor"; }
function userById(data, userId) { return data.users.find((user) => user.id === userId); }
function siteById(data, siteId) { return data.sites.find((site) => site.id === siteId); }
function profileByUserId(data, userId) { return (data.technicianProfiles || []).find((profile) => profile.userId === userId); }
function technicianOptionLabel(data, person) { const profile = profileByUserId(data, person.id); const details = [profile?.availability, profile?.region, (profile?.skills || []).slice(0, 2).join(", ")].filter(Boolean).join(" · "); return details ? `${person.name} — ${details}` : person.name; }
function TechnicianAssignment({ data, userId }) { const person = userById(data, userId); const profile = profileByUserId(data, userId); if (!person) return <span>Unassigned</span>; const details = [profile?.availability, profile?.region, (profile?.skills || []).slice(0, 2).join(", ")].filter(Boolean).join(" · "); return <span className="technician-assignment"><b>{person.name}</b>{details && <small>{details}</small>}</span>; }
function statusTone(status) { return ({ Open: "red", Triaged: "amber", Assigned: "purple", Scheduled: "purple", "In progress": "blue", Completed: "green", Active: "green", Attention: "amber", Offline: "red" })[status] || "gray"; }

export default function App() {
  const [data, setData] = useState(readWorkspace);
  const [sessionId, setSessionId] = useState(() => window.sessionStorage.getItem("tactivo-session") || "");
  const [view, setView] = useState("dashboard");
  const [editing, setEditing] = useState(null);
  const [message, setMessage] = useState("");
  const [search, setSearch] = useState("");
  const [menuOpen, setMenuOpen] = useState(false);
  const uploadRef = useRef(null);
  const user = userById(data, sessionId);

  useEffect(() => window.localStorage.setItem(STORAGE_KEY, JSON.stringify(data)), [data]);
  useEffect(() => { if (sessionId) window.sessionStorage.setItem("tactivo-session", sessionId); else window.sessionStorage.removeItem("tactivo-session"); }, [sessionId]);
  useEffect(() => { if (!message) return undefined; const timer = window.setTimeout(() => setMessage(""), 3200); return () => window.clearTimeout(timer); }, [message]);

  const save = (next, messageText, activityMessage) => {
    const activities = activityMessage ? [{ id: id("activity"), message: activityMessage, actorId: user.id, createdAt: now() }, ...next.activities].slice(0, 300) : next.activities;
    setData({ ...next, activities });
    setMessage(messageText);
  };
  const signOut = () => { setSessionId(""); setView("dashboard"); setMenuOpen(false); };
  const remove = (type, record) => {
    if (!window.confirm(`Delete ${record.name || record.title || record.reference}? This cannot be undone.`)) return;
    if (type === "user") {
      if (record.id === user.id) return setMessage("You cannot remove your own active account.");
      if (record.role === "admin" && data.users.filter((item) => item.role === "admin" && item.active).length === 1) return setMessage("At least one active Admin must remain.");
      return save({ ...data, users: data.users.filter((item) => item.id !== record.id) }, "User removed", `${record.name} was removed from team access.`);
    }
    const collection = type === "site" ? "sites" : type === "asset" ? "assets" : type === "request" ? "requests" : type === "work" ? "workOrders" : "checklists";
    save({ ...data, [collection]: data[collection].filter((item) => item.id !== record.id) }, "Record deleted", `${record.name || record.title || record.reference} was deleted.`);
  };
  const signIn = (selectedId, pin) => {
    const selected = userById(data, selectedId);
    if (!selected || !selected.active || selected.pin !== pin) return "The account or passcode is incorrect.";
    setSessionId(selected.id); setMessage(`Welcome, ${selected.name}.`); return "";
  };
  const registerAdmin = ({ name, email, pin }) => {
    const cleanName = name.trim(); const cleanEmail = email.trim().toLowerCase();
    if (data.users.some((person) => person.active)) return "A FieldOps account already exists. Sign in, then use Team access to create additional users.";
    if (!cleanName || !cleanEmail || pin.length < 6) return "Enter your name, work email, and a passcode of at least six characters.";
    if (data.users.some((person) => person.email.toLowerCase() === cleanEmail)) return "An account with that email already exists. Sign in instead.";
    const account = { id: id("user"), name: cleanName, email: cleanEmail, role: "admin", pin, active: true };
    const next = { ...data, users: [...data.users, account], activities: [{ id: id("activity"), message: `${cleanName} created an Administrator account.`, actorId: account.id, createdAt: now() }, ...data.activities] };
    setData(next); setSessionId(account.id); setMessage(`Administrator account created. Welcome, ${cleanName}.`); return "";
  };
  const exportBackup = () => {
    const blob = new Blob([JSON.stringify({ application: "Tactivo FieldOps", exportedAt: now(), data }, null, 2)], { type: "application/json" });
    const link = document.createElement("a"); link.href = URL.createObjectURL(blob); link.download = `tactivo-fieldops-${now().slice(0, 10)}.json`; link.click(); URL.revokeObjectURL(link.href); setMessage("Backup downloaded");
  };
  const restoreBackup = async (file) => { try { const backup = JSON.parse(await file.text()); if (!backup?.data?.users || !backup?.data?.sites) throw new Error(); if (!window.confirm("Replace the current records with this backup?")) return; setData(backup.data); setMessage("Backup restored"); } catch { setMessage("That file is not a valid FieldOps backup."); } finally { if (uploadRef.current) uploadRef.current.value = ""; } };
  const resetPasscode = (record) => {
    if (user.role !== "admin") { setMessage("Only an Admin can reset passcodes."); return; }
    const nextPin = window.prompt(`Set a new passcode for ${record.name}. Use at least 6 characters.`, "");
    if (nextPin === null) return;
    const cleanPin = nextPin.trim();
    if (cleanPin.length < 6) { setMessage("Passcode must be at least 6 characters."); return; }
    save({ ...data, users: data.users.map((item) => item.id === record.id ? { ...item, pin: cleanPin } : item) }, "Passcode reset", `Passcode reset for ${record.name}.`);
  };

    const requestPasswordReset = (email) => {
    const cleanEmail = email.trim().toLowerCase();
    if (!cleanEmail || !cleanEmail.includes("@")) return { error: "Enter the email address used for your FieldOps account." };
    const account = data.users.find((person) => person.active && person.email.toLowerCase() === cleanEmail);
    if (!account) return { error: "If an active account matches that email, a reset code will be available." };
    const code = String(Math.floor(100000 + Math.random() * 900000));
    const reset = { id: id("reset"), userId: account.id, code, createdAt: now(), expiresAt: Date.now() + 15 * 60 * 1000 };
    setData({ ...data, passwordResets: [...(data.passwordResets || []).filter((item) => item.userId !== account.id), reset] });
    return { email: account.email, code, message: "A one-time reset code was generated for this local FieldOps workspace." };
  };
  const resetPassword = ({ email, code, pin, confirmPin }) => {
    const cleanEmail = email.trim().toLowerCase();
    const account = data.users.find((person) => person.active && person.email.toLowerCase() === cleanEmail);
    const reset = (data.passwordResets || []).find((item) => item.userId === account?.id);
    if (!account || !reset || reset.code !== code.trim() || Date.now() > reset.expiresAt) return "The reset code is invalid or has expired. Request a new code.";
    if (!pin || pin.length < 6) return "Passcode must be at least 6 characters.";
    if (pin !== confirmPin) return "Passcodes do not match.";
    setData({ ...data, users: data.users.map((person) => person.id === account.id ? { ...person, pin } : person), passwordResets: (data.passwordResets || []).filter((item) => item.id !== reset.id), activities: [{ id: id("activity"), message: `${account.name} updated their FieldOps passcode.`, actorId: account.id, createdAt: now() }, ...data.activities].slice(0, 300) });
    setMessage("Passcode updated. You can now sign in.");
    return "";
  };
  if (!user) return <Login data={data} onLogin={signIn} onRegister={registerAdmin} onRequestReset={requestPasswordReset} onResetPassword={resetPassword} />;
  const nav = [["dashboard", "Command centre"], ["requests", "Maintenance requests"], ["work", "Work orders"], ["sites", "Customer sites"], ["assets", "Assets & equipment"], ["checklists", "Checklist library"], ["profiles", "Technician profiles"], ["team", "Team access"]].filter(([key]) => key !== "team" || user.role === "admin");
  const page = {
    dashboard: <Dashboard data={data} user={user} setView={setView} setEditing={setEditing} />,
    requests: <Requests data={data} user={user} setEditing={setEditing} remove={remove} search={search} />,
    work: <WorkOrders data={data} user={user} setEditing={setEditing} remove={remove} save={save} search={search} />,
    sites: <Sites data={data} user={user} setEditing={setEditing} remove={remove} search={search} />,
    assets: <Assets data={data} user={user} setEditing={setEditing} remove={remove} search={search} />,
    checklists: <Checklists data={data} user={user} setEditing={setEditing} remove={remove} search={search} />,
    profiles: <TechnicianProfiles data={data} user={user} setEditing={setEditing} search={search} />,
    team: <Team data={data} user={user} setEditing={setEditing} remove={remove} exportBackup={exportBackup} importRef={uploadRef} restoreBackup={restoreBackup} resetPasscode={resetPasscode} />,
  }[view];
  return <div className="fieldops-shell">
    <aside className={`sidepanel ${menuOpen ? "show" : ""}`}>
      <button className="brand-lockup" onClick={() => setView("dashboard")} aria-label="Tactivo FieldOps home"><img src={LOGO} alt="Tactivo Technologies" /><span><b>TACTIVO</b><small>FIELDOPS</small></span></button>
      <div className="operator"><i>{initials(user.name)}</i><div><strong>{user.name}</strong><small>{ROLE_LABELS[user.role]}</small></div></div>
      <nav>{nav.map(([key, label]) => <button key={key} className={view === key ? "active" : ""} onClick={() => { setView(key); setSearch(""); setMenuOpen(false); }}><span>{label}</span><b>›</b></button>)}</nav>
      <button className="signout" onClick={signOut}>Sign out / Log out</button>
    </aside>
    {menuOpen && <button className="scrim" onClick={() => setMenuOpen(false)} aria-label="Close navigation" />}
    <main className="workspace">
      <header className="topbar"><button className="menu-toggle" onClick={() => setMenuOpen(true)}>Menu</button><div className="top-title"><small>TACTIVO TECHNOLOGIES</small><strong>Service operations</strong></div><div className="top-user"><span>{ROLE_LABELS[user.role]}</span><i>{initials(user.name)}</i></div></header>
      <section className="content"><div className="breadcrumb">FieldOps <b>›</b> {nav.find(([key]) => key === view)?.[1]}</div>{["requests", "work", "sites", "assets", "checklists"].includes(view) && <input className="record-search" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search records" />}{page}</section>
    </main>
    {editing && (editing.type === "evidence" ? <EvidenceEditor record={editing.record} data={data} user={user} close={() => setEditing(null)} save={save} /> : editing.type === "profile" ? <ProfileEditor record={editing.record} data={data} close={() => setEditing(null)} save={save} /> : <Editor type={editing.type} record={editing.record} data={data} user={user} close={() => setEditing(null)} save={save} />)}
    {message && <div className="toast">{message}</div>}
  </div>;
}

function Login({ data, onLogin, onRegister, onRequestReset, onResetPassword }) {
  const [selectedId, setSelectedId] = useState(data.users.find((user) => user.role === "admin")?.id || "");
  const [pin, setPin] = useState("");
  const [error, setError] = useState("");
  const [mode] = useState(() => data.users.some((user) => user.active) ? "signin" : "signup");
  const [screen, setScreen] = useState("signin");
  const [registration, setRegistration] = useState({ name: "", email: "", pin: "", confirmPin: "" });
  const [reset, setReset] = useState({ email: "", code: "", pin: "", confirmPin: "" });
  const [resetCode, setResetCode] = useState("");
  const submit = (event) => { event.preventDefault(); const result = onLogin(selectedId, pin); setError(result); };
  const setRegistrationValue = (key, value) => setRegistration((current) => ({ ...current, [key]: value }));
  const setResetValue = (key, value) => setReset((current) => ({ ...current, [key]: value }));
  const register = (event) => { event.preventDefault(); if (registration.pin !== registration.confirmPin) return setError("Passcodes do not match."); const result = onRegister(registration); setError(result); };
  const requestReset = (event) => { event.preventDefault(); const result = onRequestReset(reset.email); setError(result.error || ""); if (result.code) { setResetCode(result.code); setScreen("reset"); } };
  const completeReset = (event) => { event.preventDefault(); const result = onResetPassword(reset); setError(result); if (!result) { setReset({ email: "", code: "", pin: "", confirmPin: "" }); setResetCode(""); setScreen("signin"); } };
  return <main className="login-page"><section className="login-brand"><img src={LOGO} alt="Tactivo Technologies logo" /><div className="brand-type"><b>TACTIVO</b><span>FIELDOPS</span></div><p>Maintenance and field service operations, coordinated with clarity.</p><ul><li>Role-based workspaces for every team member</li><li>Evidence-led service delivery</li><li>Customer site and asset visibility</li></ul></section><section className="login-card">{mode === "signin" && screen === "signin" ? <><small>TACTIVO FIELDOPS ACCESS</small><h1>Sign in to FieldOps</h1><p>Use your FieldOps account to access your role-based workspace.</p><form onSubmit={submit}><label>Account<select value={selectedId} onChange={(event) => setSelectedId(event.target.value)} required>{data.users.filter((user) => user.active).map((user) => <option key={user.id} value={user.id}>{user.name} — {ROLE_LABELS[user.role]}</option>)}</select></label><label>Passcode<input value={pin} onChange={(event) => setPin(event.target.value)} type="password" placeholder="Enter passcode" autoComplete="current-password" required /></label>{error && <p className="login-error">{error}</p>}<button type="submit">Sign in</button></form><button className="login-link" type="button" onClick={() => { setError(""); setReset({ email: "", code: "", pin: "", confirmPin: "" }); setScreen("request"); }}>Forgot your passcode?</button><p className="access-note">Need access? Ask a FieldOps Administrator to create your account from Team access.</p></> : mode === "signin" && screen === "request" ? <><small>ACCOUNT RECOVERY</small><h1>Forgot your passcode?</h1><p>Enter your work email. We will generate a one-time code for the matching active account.</p><form onSubmit={requestReset}><label>Work email<input value={reset.email} onChange={(event) => setResetValue("email", event.target.value)} type="email" autoComplete="email" required /></label>{error && <p className="login-error">{error}</p>}<button type="submit">Generate reset code</button></form><button className="login-link" type="button" onClick={() => { setError(""); setScreen("signin"); }}>Back to sign in</button><p className="access-note">For this local workspace, the one-time code is shown on the next screen instead of being emailed.</p></> : mode === "signin" ? <><small>ACCOUNT RECOVERY</small><h1>Set a new passcode</h1><p>Enter the six-digit code and choose a new passcode. The code expires in 15 minutes and can only be used once.</p>{resetCode && <div className="reset-code"><span>Local reset code</span><b>{resetCode}</b></div>}<form onSubmit={completeReset}><label>Work email<input value={reset.email} onChange={(event) => setResetValue("email", event.target.value)} type="email" autoComplete="email" required /></label><label>One-time code<input value={reset.code} onChange={(event) => setResetValue("code", event.target.value)} inputMode="numeric" pattern="[0-9]{6}" maxLength="6" required /></label><label>New passcode<input value={reset.pin} onChange={(event) => setResetValue("pin", event.target.value)} type="password" autoComplete="new-password" minLength="6" required /></label><label>Confirm new passcode<input value={reset.confirmPin} onChange={(event) => setResetValue("confirmPin", event.target.value)} type="password" autoComplete="new-password" minLength="6" required /></label>{error && <p className="login-error">{error}</p>}<button type="submit">Update passcode</button></form><button className="login-link" type="button" onClick={() => { setError(""); setScreen("signin"); }}>Back to sign in</button></> : <><small>FIRST-RUN ADMINISTRATOR REGISTRATION</small><h1>Create your Administrator account</h1><p>Create the first FieldOps account. After registration, you can sign in, add your technicians and team members, and assign their roles from Team access.</p><form onSubmit={register}><label>Full name<input value={registration.name} onChange={(event) => setRegistrationValue("name", event.target.value)} autoComplete="name" required /></label><label>Work email<input value={registration.email} onChange={(event) => setRegistrationValue("email", event.target.value)} type="email" autoComplete="email" required /></label><label>Passcode<input value={registration.pin} onChange={(event) => setRegistrationValue("pin", event.target.value)} type="password" placeholder="At least 6 characters" autoComplete="new-password" required /></label><label>Confirm passcode<input value={registration.confirmPin} onChange={(event) => setRegistrationValue("confirmPin", event.target.value)} type="password" placeholder="Re-enter passcode" autoComplete="new-password" required /></label>{error && <p className="login-error">{error}</p>}<button type="submit">Create Administrator account</button></form><p className="access-note">This local setup screen appears only before the first active account exists.</p></>}</section></main>;
}
function Dashboard({ data, user, setView, setEditing }) {
  const activeWork = data.workOrders.filter((order) => order.status !== "Completed");
  const attention = data.requests.filter((request) => request.priority === "Critical" && request.status !== "Completed");
  const profiles = (data.technicianProfiles || []).filter((profile) => userById(data, profile.userId)?.active);
  return <><div className="page-heading"><div><small>OPERATIONS PULSE</small><h1>Command centre</h1><p>Track maintenance demand, dispatch capacity, and service delivery across Tactivo customer sites.</p></div><div>{canCreateRequest(user.role) && <button className="primary" onClick={() => setEditing({ type: "request" })}>New maintenance request</button>}{canManage(user.role) && <button className="secondary" onClick={() => setEditing({ type: "work" })}>Plan work order</button>}</div></div><div className="metrics"><Metric label="Open work orders" value={activeWork.length} note="Active service commitments" onClick={() => setView("work")} /><Metric label="Critical requests" value={attention.length} note="Needs management attention" onClick={() => setView("requests")} /><Metric label="Customer sites" value={data.sites.length} note="Covered in the portfolio" onClick={() => setView("sites")} /><Metric label="Field technicians" value={profiles.length} note="Profiled service team" onClick={() => setView("profiles")} /></div><div className="dashboard-grid"><section className="panel"><header><small>WORK QUEUE</small><h2>Recent maintenance requests</h2><button onClick={() => setView("requests")}>View all</button></header>{data.requests.slice(0, 4).map((request) => <RecordLine key={request.id} title={request.title} meta={siteById(data, request.siteId)?.name} tag={request.status} />)}{!data.requests.length && <Empty text="No maintenance requests yet. Create the first request to begin dispatch." />}</section><section className="panel dark"><header><small>TEAM AVAILABILITY</small><h2>Service coverage</h2></header>{profiles.map((profile) => { const person = userById(data, profile.userId); const assigned = data.workOrders.filter((order) => order.assigneeId === profile.userId && order.status !== "Completed").length; return <div className="availability" key={profile.id}><i>{initials(person?.name)}</i><div><b>{person?.name}</b><span>{profile.region || "Zambia"} · {(profile.skills || []).slice(0, 2).join(", ") || "Skills not set"}</span></div><em>{assigned ? `${assigned} assigned` : profile.availability}</em></div>; })}</section></div><section className="panel"><header><small>ACTIVITY HISTORY</small><h2>Latest service activity</h2></header>{data.activities.slice(0, 6).map((activity) => <RecordLine key={activity.id} title={activity.message} meta={`${userById(data, activity.actorId)?.name || "Tactivo Team"} · ${shortDate(activity.createdAt)}`} />)}</section></>;
}

function Metric({ label, value, note, onClick }) { return <button className="metric-card" onClick={onClick}><small>{label}</small><b>{value}</b><span>{note}</span></button>; }
function RecordLine({ title, meta, tag }) { return <article className="record-line"><div><strong>{title}</strong><span>{meta}</span></div>{tag && <em className={`tag ${statusTone(tag)}`}>{tag}</em>}</article>; }
function Empty({ text }) { return <div className="empty-state">{text}</div>; }
function visible(records, search, resolver) { const query = search.trim().toLowerCase(); return query ? records.filter((record) => resolver(record).toLowerCase().includes(query)) : records; }

function Requests({ data, user, setEditing, remove, search }) { const rows = visible(data.requests.filter((record) => user.role !== "requestor" || record.requestorId === user.id), search, (record) => `${record.reference} ${record.title} ${siteById(data, record.siteId)?.name || ""}`); return <section><div className="page-heading compact"><div><small>WORK INTAKE</small><h1>Maintenance requests</h1><p>Capture a site issue, prioritise its response, and convert it into a service work order.</p></div>{canCreateRequest(user.role) && <button className="primary" onClick={() => setEditing({ type: "request" })}>New request</button>}</div><List headers={["Reference", "Maintenance request", "Site", "Priority", "Status", "Actions"]}>{rows.map((record) => <div className="list-row request-grid" key={record.id}><code>{record.reference}</code><div><b>{record.title}</b><span>{record.summary}</span></div><span>{siteById(data, record.siteId)?.name}</span><em className={`tag ${statusTone(record.priority)}`}>{record.priority}</em><em className={`tag ${statusTone(record.status)}`}>{record.status}</em><Actions user={user} editable={canManage(user.role) || (user.role === "requestor" && record.requestorId === user.id)} edit={() => setEditing({ type: "request", record })} remove={() => remove("request", record)} /></div>)}{!rows.length && <Empty text="No maintenance requests found." />}</List></section>; }
function WorkOrders({ data, user, setEditing, remove, save, search }) {
  const rows = visible(data.workOrders.filter((record) => user.role !== "technician" || record.assigneeId === user.id), search, (record) => `${record.reference} ${record.title} ${siteById(data, record.siteId)?.name || ""}`);
  const canDocument = (record) => canManage(user.role) || (user.role === "technician" && record.assigneeId === user.id);
  const advance = (record) => {
    if (record.status === "In progress" && !record.evidence?.signature) { setEditing({ type: "evidence", record }); return; }
    const status = record.status === "Scheduled" ? "In progress" : "Completed";
    save({ ...data, workOrders: data.workOrders.map((item) => item.id === record.id ? { ...item, status } : item) }, `Work order marked ${status}`, `${record.reference} moved to ${status}.`);
  };
  return <section><div className="page-heading compact"><div><small>SERVICE DELIVERY</small><h1>Work orders</h1><p>Plan site visits, assign technicians, and capture complete service evidence.</p></div>{canManage(user.role) && <button className="primary" onClick={() => setEditing({ type: "work" })}>Create work order</button>}</div><List headers={["Reference", "Work order", "Technician", "Status", "Scheduled", "Actions"]}>{rows.map((record) => <div className="list-row work-grid" key={record.id}><code>{record.reference}</code><div><b>{record.title}</b><span>{siteById(data, record.siteId)?.name}</span></div><TechnicianAssignment data={data} userId={record.assigneeId} /><em className={`tag ${statusTone(record.status)}`}>{record.status}</em><span>{shortDate(record.scheduledAt)}</span><Actions editable={canManage(user.role)} edit={() => setEditing({ type: "work", record })} remove={() => remove("work", record)} extra={<>{canDocument(record) && <button onClick={() => setEditing({ type: "evidence", record })}>{record.evidence?.signature ? "Evidence" : "Add evidence"}</button>}{user.role === "technician" && record.assigneeId === user.id && record.status !== "Completed" && <button onClick={() => advance(record)}>Update status</button>}</>} /></div>)}{!rows.length && <Empty text="No work orders found. Plan work or create one from a maintenance request." />}</List></section>;
}
function Sites({ data, user, setEditing, remove, search }) { const rows = visible(data.sites, search, (record) => `${record.name} ${record.customer} ${record.location}`); return <section><div className="page-heading compact"><div><small>SERVICE CATALOGUE</small><h1>Customer sites</h1><p>Manage the site register used throughout maintenance requests and work orders.</p></div>{canManage(user.role) && <button className="primary" onClick={() => setEditing({ type: "site" })}>Add site</button>}</div><div className="site-grid">{rows.map((record) => <article className="site-card" key={record.id}><em className={`tag ${statusTone(record.status)}`}>{record.status}</em><h2>{record.name}</h2><b>{record.customer}</b><p>{record.location}</p><small>{record.contact}</small>{canManage(user.role) && <Actions user={user} editable edit={() => setEditing({ type: "site", record })} remove={() => remove("site", record)} />}</article>)}{!rows.length && <Empty text="No sites match this search." />}</div></section>; }
function Assets({ data, user, setEditing, remove, search }) { const rows = visible(data.assets, search, (record) => `${record.name} ${record.tag} ${record.category} ${siteById(data, record.siteId)?.name || ""}`); return <section><div className="page-heading compact"><div><small>SERVICE CATALOGUE</small><h1>Assets & equipment</h1><p>Track customer equipment and link service work to the correct operational asset.</p></div>{canManage(user.role) && <button className="primary" onClick={() => setEditing({ type: "asset" })}>Add asset</button>}</div><List headers={["Asset", "Asset tag", "Customer site", "Category", "Condition", "Actions"]}>{rows.map((record) => <div className="list-row asset-grid" key={record.id}><b>{record.name}</b><code>{record.tag}</code><span>{siteById(data, record.siteId)?.name}</span><span>{record.category}</span><em className={`tag ${statusTone(record.status)}`}>{record.status}</em><Actions user={user} editable={canManage(user.role)} edit={() => setEditing({ type: "asset", record })} remove={() => remove("asset", record)} /></div>)}{!rows.length && <Empty text="No assets have been registered. Add the first asset to start equipment maintenance tracking." />}</List></section>; }
function Checklists({ data, user, setEditing, remove, search }) { const rows = visible(data.checklists, search, (record) => `${record.name} ${record.discipline} ${record.points.join(" ")}`); return <section><div className="page-heading compact"><div><small>QUALITY CONTROL</small><h1>Checklist library</h1><p>Use Tactivo service templates to make every maintenance visit consistent and auditable.</p></div>{canManage(user.role) && <button className="primary" onClick={() => setEditing({ type: "checklist" })}>Add checklist</button>}</div><div className="checklist-grid">{rows.map((record) => <article className="check-card" key={record.id}><em className="tag purple">{record.discipline}</em><h2>{record.name}</h2><ul>{record.points.map((point) => <li key={point}>{point}</li>)}</ul>{canManage(user.role) && <Actions user={user} editable edit={() => setEditing({ type: "checklist", record })} remove={() => remove("checklist", record)} />}</article>)}</div></section>; }
function TechnicianProfiles({ data, user, setEditing, search }) { const profiles = visible(data.technicianProfiles || [], search, (profile) => { const person = userById(data, profile.userId) || {}; return `${person.name || ""} ${profile.region} ${(profile.skills || []).join(" ")} ${(profile.certifications || []).join(" ")}`; }); return <section><div className="page-heading compact"><div><small>FIELD CAPABILITY</small><h1>Technician profiles</h1><p>Maintain each technician’s skills, certifications, availability, and service coverage.</p></div>{user.role === "admin" && <button className="primary" onClick={() => setEditing({ type: "profile" })}>Add technician profile</button>}</div><div className="site-grid">{profiles.map((profile) => { const person = userById(data, profile.userId) || {}; const assigned = data.workOrders.filter((order) => order.assigneeId === profile.userId && order.status !== "Completed").length; return <article className="site-card profile-card" key={profile.id}><em className={`tag ${statusTone(profile.availability)}`}>{profile.availability}</em><div className="person"><i>{initials(person.name)}</i><div><h2>{person.name || "Unlinked technician"}</h2><b>{person.email}</b></div></div><p>{profile.region || "Service region not set"} · {profile.phone || "Phone not set"}</p><small><b>Skills:</b> {(profile.skills || []).join(" · ") || "Not set"}</small><small><b>Certifications:</b> {(profile.certifications || []).join(" · ") || "Not set"}</small><small><b>Active assignments:</b> {assigned}</small>{(user.role === "admin" || user.id === profile.userId) && <div className="actions"><button onClick={() => setEditing({ type: "profile", record: profile })}>Edit profile</button></div>}</article>; })}{!profiles.length && <Empty text="No technician profiles have been added." />}</div></section>; }
function Team({ data, user, setEditing, remove, exportBackup, importRef, restoreBackup, resetPasscode }) { return <section><div className="page-heading compact"><div><small>ADMINISTRATION</small><h1>Team access</h1><p>Create team accounts and assign their FieldOps roles. This area is restricted to Admins.</p></div><button className="primary" onClick={() => setEditing({ type: "user" })}>Add user</button></div><div className="admin-tools"><button onClick={exportBackup}>Export backup</button><button onClick={() => importRef.current?.click()}>Restore backup</button><input ref={importRef} type="file" accept="application/json" onChange={(event) => restoreBackup(event.target.files?.[0])} hidden /></div><List headers={["User", "Email", "Role", "Account status", "Actions"]}>{data.users.map((person) => <div className="list-row team-grid" key={person.id}><div className="person"><i>{initials(person.name)}</i><b>{person.name}</b></div><span>{person.email}</span><em className="tag purple">{ROLE_LABELS[person.role]}</em><em className={`tag ${person.active ? "green" : "red"}`}>{person.active ? "Active" : "Suspended"}</em><Actions user={user} editable edit={() => setEditing({ type: "user", record: person })} remove={() => remove("user", person)} extra={<button type="button" onClick={() => resetPasscode(person)}>Reset passcode</button>} /></div>)}</List></section>; }
function List({ headers, children }) { return <div className="record-list"><div className="list-head">{headers.map((header) => <span key={header}>{header}</span>)}</div>{children}</div>; }
function Actions({ editable, edit, remove, extra }) { return <div className="actions">{extra}{editable && <button onClick={edit}>Edit</button>}{editable && <button className="delete" onClick={remove}>Delete</button>}</div>; }

function Editor({ type, record = {}, data, user, close, save }) {
  const [form, setForm] = useState(() => ({ ...record }));
  const [error, setError] = useState("");
  const set = (key, value) => setForm((current) => ({ ...current, [key]: value }));
  const title = `${record.id ? "Edit" : "Create"} ${type === "work" ? "work order" : type}`;
  const submit = (event) => { event.preventDefault(); const stamp = now(); let next = data; let message = ""; let activity = "";
